                "mode": "normal",
                "text": "// budget-guardrail.ts\nexport class DailySpendGuardrail {\n  private dailyBudgetUSD: number;\n  private currentSpentUSD: number = 0;\n  private resetDate: string;\n\n  constructor(dailyBudgetUSD: number) {\n    this.dailyBudgetUSD = dailyBudgetUSD;\n    this.resetDate = new Date().toISOString().slice(0, 10);\n  }\n\n  private checkAndResetWindow(): void {\n    const today = new Date().toISOString().slice(0, 10);\n    if (today !== this.resetDate) {\n      this.currentSpentUSD = 0;\n      this.resetDate = today;\n    }\n  }\n\n  public assertBudgetAvailable(): void {\n    this.checkAndResetWindow();\n    if (this.currentSpentUSD >= this.dailyBudgetUSD) {\n      throw new Error(\n        `[CIRCUIT_BREAKER_TRIGGERED] Daily LLM budget limit reached ($${this.dailyBudgetUSD}). Request blocked.`\n      );\n    }\n  }\n\n  public recordExpense(costUSD: number): void {\n    this.checkAndResetWindow();\n    this.currentSpentUSD += costUSD;\n    console.info(`[BUDGET_TRACKER] Total spent today: $${this.currentSpentUSD.toFixed(4)} / $${this.dailyBudgetUSD}`);\n  }\n}",
