            "children": [
              {
                "mode": "normal",
                "text": "// batcher.ts\ntype Task = () => void;\n\nclass BatchScheduler {\n  private queue: Set<Task> = new Set();\n  private isFlushing: boolean = false;\n\n  public schedule(task: Task): void {\n    this.queue.add(task);\n\n    if (!this.isFlushing) {\n      this.isFlushing = true;\n\n      // Memanfaatkan microtask queue native browser/Node.js\n      queueMicrotask(() => {\n        this.flush();\n      });\n    }\n  }\n\n  private flush(): void {\n    try {\n      console.log(`[BatchScheduler] Memproses ${this.queue.size} task sekaligus dalam 1 tick.`);\n      this.queue.forEach((task) => task());\n    } finally {\n      this.queue.clear();\n      this.isFlushing = false;\n    }\n  }\n}\n\n// Demo penggunaan:\nconst scheduler = new BatchScheduler();\n\nfunction updateDOM(component: string) {\n  console.log(`Render DOM untuk: ${component}`);\n}\n\n// Simulasi mutasi beruntun dalam satu synchronous execution block\nconsole.log(\"Start synchronous execution\");\n\nscheduler.schedule(() => updateDOM(\"Sidebar\"));\nscheduler.schedule(() => updateDOM(\"Header\"));\nscheduler.schedule(() => updateDOM(\"Sidebar\")); // Duplikat diabaikan oleh Set\n\nconsole.log(\"End synchronous execution\");\n\n// Output di konsol:\n// Start synchronous execution\n// End synchronous execution\n// [BatchScheduler] Memproses 2 task sekaligus dalam 1 tick.\n// Render DOM untuk: Sidebar\n// Render DOM untuk: Header",
                "type": "code-highlight",
                "style": "",
                "detail": 0,
                "format": 0,
                "version": 1
              }
            ],
