            "children": [
              {
                "type": "listitem",
                "value": 1,
                "format": "",
                "indent": 0,
                "version": 1,
                "children": [
                  {
                    "mode": "normal",
                    "text": "CREATE TABLE orders",
                    "type": "text",
                    "style": "",
                    "detail": 0,
                    "format": 16,
                    "version": 1
                  },
                  {
                    "mode": "normal",
                    "text": ": Menggunakan tipe data ",
                    "type": "text",
                    "style": "",
                    "detail": 0,
                    "format": 0,
                    "version": 1
                  },
                  {
                    "mode": "normal",
                    "text": "BIGSERIAL",
                    "type": "text",
                    "style": "",
                    "detail": 0,
                    "format": 16,
                    "version": 1
                  },
                  {
                    "mode": "normal",
                    "text": " untuk primary key untuk mencegah kehabisan integer (",
                    "type": "text",
                    "style": "",
                    "detail": 0,
                    "format": 0,
                    "version": 1
                  },
                  {
                    "mode": "normal",
                    "text": "BIGINT",
                    "type": "text",
                    "style": "",
                    "detail": 0,
                    "format": 16,
                    "version": 1
                  },
                  {
                    "mode": "normal",
                    "text": " menampung hingga $9 \\times 10^{18}$ ID). Kolom ",
                    "type": "text",
                    "style": "",
                    "detail": 0,
                    "format": 0,
                    "version": 1
                  },
                  {
                    "mode": "normal",
                    "text": "created_at",
                    "type": "text",
                    "style": "",
                    "detail": 0,
                    "format": 16,
                    "version": 1
                  },
                  {
                    "mode": "normal",
                    "text": " menggunakan ",
                    "type": "text",
                    "style": "",
                    "detail": 0,
                    "format": 0,
                    "version": 1
                  },
                  {
                    "mode": "normal",
                    "text": "TIMESTAMPTZ",
                    "type": "text",
                    "style": "",
                    "detail": 0,
                    "format": 16,
                    "version": 1
                  },
                  {
                    "mode": "normal",
                    "text": " (Timezone Aware UTC).",
                    "type": "text",
                    "style": "",
                    "detail": 0,
                    "format": 0,
                    "version": 1
                  }
                ],
                "direction": "ltr"
              },
              {
                "type": "listitem",
                "value": 2,
                "format": "",
                "indent": 0,
                "version": 1,
                "children": [
                  {
                    "mode": "normal",
                    "text": "CREATE INDEX idx_orders_user_created",
                    "type": "text",
                    "style": "",
                    "detail": 0,
                    "format": 16,
                    "version": 1
                  },
                  {
                    "mode": "normal",
                    "text": ": Ini adalah ",
                    "type": "text",
                    "style": "",
                    "detail": 0,
                    "format": 0,
                    "version": 1
                  },
                  {
                    "mode": "normal",
                    "text": "Composite Index",
                    "type": "text",
                    "style": "",
                    "detail": 0,
                    "format": 1,
                    "version": 1
                  },
                  {
                    "mode": "normal",
                    "text": ". Urutan kolom sangat berpengaruh (",
                    "type": "text",
                    "style": "",
                    "detail": 0,
                    "format": 0,
                    "version": 1
                  },
                  {
                    "mode": "normal",
                    "text": "Leftmost Prefix Rule",
                    "type": "text",
                    "style": "",
                    "detail": 0,
                    "format": 2,
                    "version": 1
                  },
                  {
                    "mode": "normal",
                    "text": "). Karena kita selalu memfilter ",
                    "type": "text",
                    "style": "",
                    "detail": 0,
                    "format": 0,
                    "version": 1
                  },
                  {
                    "mode": "normal",
                    "text": "user_id",
                    "type": "text",
                    "style": "",
                    "detail": 0,
                    "format": 16,
                    "version": 1
                  },
                  {
                    "mode": "normal",
                    "text": " lalu mengurutkan ",
                    "type": "text",
                    "style": "",
                    "detail": 0,
                    "format": 0,
                    "version": 1
                  },
                  {
                    "mode": "normal",
                    "text": "created_at DESC",
                    "type": "text",
                    "style": "",
                    "detail": 0,
                    "format": 16,
                    "version": 1
                  },
                  {
                    "mode": "normal",
                    "text": ", index ini memungkinkan database langsung melompat ke node user yang bersangkutan dan membaca data secara berurutan tanpa proses in-memory sorting tambahan.",
                    "type": "text",
                    "style": "",
                    "detail": 0,
                    "format": 0,
                    "version": 1
                  }
                ],
                "direction": "ltr"
              },
              {
                "type": "listitem",
                "value": 3,
                "format": "",
                "indent": 0,
                "version": 1,
                "children": [
                  {
                    "mode": "normal",
                    "text": "EXPLAIN ANALYZE",
                    "type": "text",
                    "style": "",
                    "detail": 0,
                    "format": 16,
                    "version": 1
                  },
                  {
                    "mode": "normal",
                    "text": ": Perintah wajib untuk profiling query. Ini menjalankan query dan menampilkan waktu eksekusi riil, apakah query menggunakan ",
                    "type": "text",
                    "style": "",
                    "detail": 0,
                    "format": 0,
                    "version": 1
                  },
                  {
                    "mode": "normal",
                    "text": "Index Scan",
                    "type": "text",
                    "style": "",
                    "detail": 0,
                    "format": 16,
                    "version": 1
                  },
                  {
                    "mode": "normal",
                    "text": " atau ",
                    "type": "text",
                    "style": "",
                    "detail": 0,
                    "format": 0,
                    "version": 1
                  },
                  {
                    "mode": "normal",
                    "text": "Seq Scan",
                    "type": "text",
                    "style": "",
                    "detail": 0,
                    "format": 16,
                    "version": 1
                  },
                  {
                    "mode": "normal",
                    "text": ".",
                    "type": "text",
                    "style": "",
                    "detail": 0,
                    "format": 0,
                    "version": 1
                  }
                ],
                "direction": "ltr"
              },
              {
                "type": "listitem",
                "value": 4,
                "format": "",
                "indent": 0,
                "version": 1,
                "children": [
                  {
                    "mode": "normal",
                    "text": "Cursor Pagination vs Offset",
                    "type": "text",
                    "style": "",
                    "detail": 0,
                    "format": 1,
                    "version": 1
                  },
                  {
                    "mode": "normal",
                    "text": ": ",
                    "type": "text",
                    "style": "",
                    "detail": 0,
                    "format": 0,
                    "version": 1
                  },
                  {
                    "mode": "normal",
                    "text": "OFFSET 50000",
                    "type": "text",
                    "style": "",
                    "detail": 0,
                    "format": 16,
                    "version": 1
                  },
                  {
                    "mode": "normal",
                    "text": " memaksa database membaca 50.000 baris pertama lalu membuangnya sebelum mengambil 20 baris berikutnya. Cursor pagination menggunakan klausa ",
                    "type": "text",
                    "style": "",
                    "detail": 0,
                    "format": 0,
                    "version": 1
                  },
                  {
                    "mode": "normal",
                    "text": "WHERE created_at < :cursor",
                    "type": "text",
                    "style": "",
                    "detail": 0,
                    "format": 16,
                    "version": 1
                  },
                  {
                    "mode": "normal",
                    "text": " sehingga database langsung melompat ke titik awal pencarian melalui index.",
                    "type": "text",
                    "style": "",
                    "detail": 0,
                    "format": 0,
                    "version": 1
                  }
                ],
                "direction": "ltr"
              }
            ],
