            "children": [
              {
                "mode": "normal",
                "text": "// naive-checkout.ts\nimport { Request, Response } from 'express';\nimport { db } from './database';\n\nexport async function handleCheckoutNaive(req: Request, res: Response) {\n  try {\n    const { userId, productId, quantity } = req.body;\n\n    // 1. Cek stok langsung ke SQL DB (Bottleneck 1)\n    const product = await db.query('SELECT stock FROM products WHERE id = $1', [productId]);\n    if (product.rows[0].stock < quantity) {\n      return res.status(400).json({ message: 'Stok habis' });\n    }\n\n    // 2. Potong stok (Bottleneck 2 - Race condition berisiko tinggi)\n    await db.query('UPDATE products SET stock = stock - $1 WHERE id = $2', [quantity, productId]);\n\n    // 3. Buat order\n    const order = await db.query(\n      'INSERT INTO orders (user_id, product_id, quantity) VALUES ($1, $2, $3) RETURNING id',\n      [userId, productId, quantity]\n    );\n\n    return res.status(200).json({ success: true, orderId: order.rows[0].id });\n  } catch (error) {\n    // Mengembalikan error generic tanpa logging kontekstual atau mekanisme pemulihan\n    return res.status(500).json({ error: 'Internal Server Error' });\n  }\n}",
                "type": "code-highlight",
                "style": "",
                "detail": 0,
                "format": 0,
                "version": 1
              }
            ],
            "language": "typescript",
            "direction": "ltr"
